const body = $input.first().json.body || {};

const taskId = body.task_id;
const subTaskId = body.sub_task_id;
const setIndex = parseInt(body.set_index) || 0;
const skuDescription = String(body.sku_description || '').trim();
const skuImage = body.sku_image || '';
const imageType = body.image_type;
const imagePosition = parseInt(body.image_position) || 1;
const callbackSecret = body.callback_secret || '';
const callbackUrl = body.callback_url || '';

const defaultPrompt = [
  '基于当前 SKU 参考图生成一张 1:1 电商规格图，主体清晰完整。',
  '严格保持参考图中的产品品类、数量、结构、包装、商标、文字、颜色、材质和配件一致。',
  '使用干净、明亮、真实的商业摄影背景，主体居中，不裁切商品。',
  '不得擅自增减商品数量，不得新增促销文案、价格、水印、边框、拼图或无关配件。',
].join('\n');
const finalPrompt = skuDescription || defaultPrompt;
const imagesArray = [skuImage].filter(Boolean);

return {
  taskId, subTaskId, setIndex, skuDescription, skuImage,
  imageType, imagePosition, finalPrompt, imagesArray, callbackSecret, callbackUrl,
};

